int partition(int v[], int esq, int dir){
    int i, pos=esq,tmp; 
    //#pragma omp parallel for schedule(guided) 
    for(i=esq+1; i<=dir; i++){
        if(v[i]<v[esq]){
            pos++;
            tmp=v[i];
            v[i]=v[pos];
            v[pos]=tmp;
        }
    }
    //swap
    tmp=v[esq];
    v[esq]=v[pos];
    v[pos]=tmp;
    return pos;
