answers.body:
The omp single nowait pragma means that the following block is to be executed by a single thread.  In this case that means that your entire loop is executed by one thread.  This should resolve your issue: void function1(int n, int j)
{
    //Serial part
    #pragma omp parallel
    {
        //execcute function1() for every n
        for (i=0; i<n; i++)    //Notice this is outside the pragma
        {
            #pragma omp single nowait    //Notice this is inside the loop
            {
                //create a task for computing only large numbers of n
                if (i <= 10)
                    //execute serial
                else
                    #pragma omp task
                    //call function again 
                    function1(n, j+1);
                    printf("task id:\n", omp_get_thread_num());
            }
        }
    }
}

