answers.body:
#pragma omp single has an implicit barrier at the end, you need to use #pragma omp single nowait if you want the two single block run concurrently. However, for your requirement, using section might be a better idea #pragma omp parallel
{
    #pragma omp sections 
    {
        #pragma omp section 
        {
            for (int i=0; i<given_number; ++i) myBuffer_1[i] = myObject_1->myFunction();  
        }
        #pragma omp section
        {
            for (int i=0; i<given_number; ++i) myBuffer_2[i] = myObject_2->myFunction();  
        }
    }

}

