            //make it the new gBest Value.
            if(abs(TARGET - testProblem(gBestTest)) < abs(TARGET - testProblem(gBest)))
            {
                gBest = gBestTest;
            }

            getVelocity(gBest);

            updateParticles(gBest);

            epoch += 1;

        }else{
            done = true;
        }

    }while(!done);

    cout << epoch << " epochs completed." << endl;

    return;
}

void initialize()
{
    int total;
    #pragma omp parallel for schedule (dynamic,5) 
    for(int i = 0; i <= MAX_PARTICLES - 1; i++)
    {
        total = 0;
        for(int j = 0; j <= MAX_INPUTS - 1; j++)
        {
            particles[i].setData(j, getRandomNumber(START_RANGE_MIN, START_RANGE_MAX));
            total += particles[i].getData(j);
        } // j
        particles[i].setpBest(total);
    } // i

    return;
}

void getVelocity(int gBestIndex)
{
/* from Kennedy & Eberhart(1995).
    vx[][] = vx[][] + 2 * rand() * (pbestx[][] - presentx[][]) + 
                      2 * rand() * (pbestx[][gbest] - presentx[][])
*/
    int testResults, bestResults;
    float vValue;

    bestResults = testProblem(gBestIndex);
    #pragma omp parallel for schedule (dynamic,5) 
    for(int i = 0; i <= MAX_PARTICLES - 1; i++)
    {
        testResults = testProblem(i);
        vValue = particles[i].getVelocity() + 
            2 * gRand() * (particles[i].getpBest() - testResults) + 2 * gRand() * 
                                                    (bestResults - testResults);

        if(vValue > V_MAX){
            particles[i].setVelocity(V_MAX);
        }else if(vValue < -V_MAX){
            particles[i].setVelocity(-V_MAX);
        }else{
            particles[i].setVelocity(vValue);
        }
    } // i
}

void updateParticles(int gBestIndex)
{
    int total, tempData;
    #pragma omp parallel for schedule (dynamic,5) 
    for(int i = 0; i <= MAX_PARTICLES - 1; i++)
    {
        for(int j = 0; j <= MAX_INPUTS - 1; j++)
        {
            if(particles[i].getData(j) != particles[gBestIndex].getData(j))
            {
                tempData = particles[i].getData(j);
                particles[i].setData(j, tempData + static_cast<int>(particles[i].getVelocity()));
            }
        } // j

        //Check pBest value.
        total = testProblem(i);
        if(abs(TARGET - total) < particles[i].getpBest())
        {
            particles[i].setpBest(total);
        }

    } // i

}

int testProblem(int index)
{
    int total = 0;

    for(int i = 0; i <= MAX_INPUTS - 1; i++)
    {
        total += particles[index].getData(i);
    } // i

    return total;
}

float gRand()
{
    // Returns a pseudo-random float between 0.0 and 1.0
    return float(rand()/(RAND_MAX + 1.0));
}

int getRandomNumber(int low, int high)
{
    // Returns a pseudo-random integer between low and high.
    return low + int(((high - low) + 1) * rand() / (RAND_MAX + 1.0)); 
}

int minimum()
{
//Returns an array index.
    int winner = 0;
    bool foundNewWinner;
    bool done = false;

    do
    {
        foundNewWinner = false;
        #pragma omp parallel for schedule (dynamic,2) 
        for(int i = 0; i <= MAX_PARTICLES - 1; i++)
        {
            if(i != winner){             //Avoid self-comparison.
                //The minimum has to be in relation to the Target.
                if(abs(TARGET - testProblem(i)) < abs(TARGET - testProblem(winner)))
                {
                    winner = i;
                    foundNewWinner = true;
                }
            }
        } // i

        if(foundNewWinner == false)
        {
            done = true;
        }

    }while(!done);

    return winner;
}

I would like to run following code in parallel in openMP: while (!stopcondition())
{       
 work_1();      
 work_2();  //work_2 has to be run after work_1
} where the work() function is easy to parallelize: work_i()
{
    //...some linear stuff...//

    #pragma omp parallel for schedule(static, 2) // make a piece of size 2 for each thread  
      for(int n=0; n<N; ++n)
         printf(" %d", omp_get_thread_num() );
} It is inconvenient to set the parallel region inside the while loop or the work() function since it causes the threads to split each time, which results in big overhead. When I tried: #pragma omp parallel
 {
    #pragma omp single
    {
        while (!stopcondition())
        {
            work_1();       
            work_2();  
        }
    }
 } Then both work_1 and work_2 always prints the same id, thus it is certainly executed by the same thread. 1) How can I overcome it?
2) Shall I just extract the // linear stuff // from work() and put it inside #pragma omp single? 3) Where is the best place to initialize the parallel region? ----------------------edit----------------- It seems that the only way is to remove the stuff from work() and enclose it in a common parallel region: while (!stopcondition())
{
    #pragma omp parallel
    {
        #pragma omp parallel for schedule(static, 2) // make a piece of size 2 for each thread  
          for(int n=0; n<N; ++n)
             printf("Piece of work_1 %d", omp_get_thread_num() );
        #pragma omp parallel for schedule(static, 2) // make a piece of size 2 for each thread  
          for(int n=0; n<N; ++n)
             printf("Piece of work_2 %d", omp_get_thread_num() );
    }

    //...rest of linear stuff...//
}

answers.body:
The problem with your last solution: while (!stopcondition())
{
    #pragma omp parallel
    {
        #pragma omp parallel for schedule(static, 2) // make a piece of size 2     for each thread  
          for(int n=0; n<N; ++n)
             printf("Piece of work_1 %d", omp_get_thread_num() );
        #pragma omp parallel for schedule(static, 2) // make a piece of size 2     for each thread  
          for(int n=0; n<N; ++n)
             printf("Piece of work_2 %d", omp_get_thread_num() );
    }

//...rest of linear stuff...//
} It's that every iteration of the loop will spawn threads, which is not good for performance. Moreover, you have nested parallel regions, which, depending on the OpenMP you are using, can create an oversubscription of threads: Each thread spawned by the first parallel will spawn a new set of threads for each inner parallel region; it's correct, but not optimal. A solution would be: #pragma omp parallel
{
  while (!stopcondition())
  {       
   work_1();      
   #pragma omp barrier /*So you make sure work_2 is executed after work_1*/
   work_2();  //work_2 has to be run after work_1
  }
} Now, depending on what your stopcondition() function does, you might need some synchronization to make sure there are no race conditions and all threads exit the loop correctly.

