    #pragma omp parallel for reduction(+:bat) private(j)        
    for(j=0; j<N3; j++) {
        D[i][j] = D[i-3][j] / 3.0 + x + E[i];
        if (D[i][j] < 6.5) bat = bat + D[i][j]/100.0;
    }
} Edit: I forgot to add the reduction and make j private.  I fixed that now.

