answers.body:
The loop you are trying to parallelise modifies the same variables x and sum in each iteration, this is very cumbersome to parallelize. You could rewrite the code to make the path to parallelisation more obvious: #include <stdio.h>
#include <omp.h>
#include <math.h>

double f(double x) {
    return sin(x) + 0.5 * x;
}

int main() {
    int n = 1 << 27, i, j;
    double a = 0, b = 9, h, x, sum, integral;
    double sums[64] = { 0 };

    double start = omp_get_wtime();
    h = fabs(b - a) / n;

    omp_set_dynamic(0);
    omp_set_num_threads(64);
    #pragma omp parallel for

    for (j = 0; j < 64; j++) {
        for (i = 0; i < n; i += 64) {
            sums[j] += f(a + i * h + j * h);
        }
    }
    sum = 0;
    for (j = 0; j < 64; j++) {
        sum += sums[i];
    }

    integral = (h / 2) * (f(a) + f(b) + 2 * sum);
    double end = omp_get_wtime();
    double time = end - start;
    printf("Execution time: %2.3f seconds\n", time);
    printf("\nThe integral is: %lf\n", integral);
    return 0;
}

