answers.body:
The answer to your question "Why can't reduction be used with OpenMP tasks?" is "It can".
However, you have to write the code in a slightly different way. Here's a marginally polished version of your code that does exactly that:- #include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <omp.h>

#define NPOINTS 2000
#define MAXITER 2000

struct complex
{
    double real;
    double imag;
};

int main()
{
  /*
   *
   *
   *     Outer loops run over npoints, initialise z=c
   *
   *     Inner loop has the iteration z=z*z+c, and threshold test
   */

  double time1 = omp_get_wtime();
  int numoutside = 0;

#pragma omp parallel default(none) shared(numoutside) 
  {
#pragma omp single
    {
#pragma omp taskgroup task_reduction(+:numoutside)
      {
        for (int i = 0; i < NPOINTS; i++)
          {
            #pragma omp task in_reduction(+:numoutside)
            {
              for (int j = 0; j < NPOINTS; j++)
                {
                  struct complex c;
                  c.real = -2.0 + 2.5 * (double)(i) / (double)(NPOINTS) + 1.0e-7;
                  c.imag = 1.125 * (double)(j) / (double)(NPOINTS) + 1.0e-7;
                  struct complex z = c;

                  for (int iter = 0; iter < MAXITER; iter++)
                    {
                      double ztemp = (z.real * z.real) - (z.imag * z.imag) + c.real;
                      z.imag = z.real * z.imag * 2 + c.imag;
                      z.real = ztemp;
                      if ((z.real * z.real + z.imag * z.imag) > 4.0e0)
                        {
                          numoutside++;
                          break;
                        }
                    }
                }
            }
          }
      }
    }
  }

  double time2 = omp_get_wtime();
  double elapsed = time2 - time1;
  printf("elapsed %f\n", elapsed);

  /*
   *  Calculate area and error and output the results
   */

  double area = 2.0 * 2.5 * 1.125 * (double)(NPOINTS * NPOINTS - numoutside) / (double)(NPOINTS * NPOINTS);
  double error = area / (double)NPOINTS;

  printf("Area of Mandlebrot set = %12.8f +/- %12.8f\n", area, error);
} I have cleaned the code up slightly by moving variable declarations to their minimal scope (something that was new in C99, so has only been available for over 20 years!). Doing that removes lots of noise in the OpenMP directives. I have also added the task reductions. This code gives the same answer as your code and runs very marginally (~1%) faster than your code when using Clang 17.0.3 on my Mac M1 machine.

