answers.body:
You use the wrong start and stop indices when creating your filter iterators. I've attached a working example. I used s to select the thread inside the parallel for statement. Not sure if your version works too, so I changed it to what I'm used to. #pragma omp parallel
{
    #pragma omp for
    for (int s = 0; s < 4; s++)
    {
        /* The following lines are important */
        FilterIter filter_iter_first(predicate, test_vec.begin() + start_vec[s], (test_vec.begin() + end_vec[s] + 1));
        FilterIter filter_iter_last(predicate, test_vec.begin() + end_vec[s] + 1, (test_vec.begin() + end_vec[s] + 1));

        for (auto iter = filter_iter_first; iter != filter_iter_last; iter++)
        {
            std::cout << "num: " << *iter << std::endl;
            (*iter) = (*iter) + 1;
        }
    }
}

