    for(int k = 0; k < WIDTH; ++k){
    ...
}

i=1
#pragma omp parallel for
for(int j = 0; j < HEIGHT; ++j){
    for(int k = 0; k < WIDTH; ++k){
    ...
}

i=2
#pragma omp parallel for
for(int j = 0; j < HEIGHT; ++j){
    for(int k = 0; k < WIDTH; ++k){
    ...
} Warning -- check the syntax yourself, this is no more than a sketch of manual loop unrolling. Try combining this and collapsing the j and k loops. Oh, and don't complain about code duplication, you've told us you're being scored partly on performance improvements.

